44	static u64 bm_dma_mask = DMA_BIT_MASK(40);
45	
46	static int bm_eth_reset_phy(struct platform_device *pdev)
47	{
48		struct device_node *np = pdev->dev.of_node;
49		int phy_reset_gpio;
50		u32	ephy_base_addr = 0x0;
51		void __iomem *ephy_base_reg;
52		u32	ephy_top_addr = 0x0;
53		void __iomem *ephy_top_reg;
54	
55		if (!np)
56			return 0;
57	
58		of_property_read_u32(np, "ephy_base_reg", &ephy_base_addr);
59		of_property_read_u32(np, "ephy_top_reg", &ephy_top_addr);
60	
61		if (ephy_base_addr && ephy_top_addr) {
62			ephy_base_reg = ioremap(ephy_base_addr, 0x80);
63			ephy_top_reg = ioremap(ephy_top_addr, 0x10);
64	#ifdef CONFIG_PM_SLEEP
65	#if defined(CONFIG_ARCH_CV180X) || defined(CONFIG_ARCH_CV181X)
66			// set rg_ephy_apb_rw_sel 0x0804@[0]=1/APB by using APB interface
67			writel(0x0001, ephy_top_reg + 0x4);
68	
69			// Release 0x0800[0]=0/shutdown
70			writel(0x0900, ephy_top_reg);
71	
72			// Release 0x0800[2]=1/dig_rst_n, Let mii_reg can be accessabile
73			writel(0x0904, ephy_top_reg);
74			// ANA INIT (PD/EN), switch to MII-page5
75			writel(0x0500, ephy_base_reg + 0x7c);
76			// Release ANA_PD p5.0x10@[13:8] = 6'b001100
77			writel(0x0c00, ephy_base_reg + 0x40);
78			// Release ANA_EN p5.0x10@[7:0] = 8'b01111110
79			writel(0x0c7e, ephy_base_reg + 0x40);
80			// Wait PLL_Lock, Lock_Status p5.0x12@[15] = 1
81			//mdelay(1);
82	
83			// Release 0x0800[1] = 1/ana_rst_n
84			writel(0x0906, ephy_top_reg);
85	
86			// ANA INIT
87			// @Switch to MII-page5
88			writel(0x0500, ephy_base_reg + 0x7c);
89			// PHY_ID
90			writel(0x0043, ephy_base_reg + 0x8);
91			writel(0x5649, ephy_base_reg + 0xc);
92			// switch to MDIO control by ETH_MAC
93			writel(0x0, ephy_top_reg + 0x4);
94	#endif
95	#endif
96			iounmap(ephy_base_reg);
97			iounmap(ephy_top_reg);
98		}
99	
100		phy_reset_gpio = of_get_named_gpio(np, "phy-reset-gpios", 0);
101	
102		if (phy_reset_gpio < 0)
103			return 0;
104	
105		if (gpio_request(phy_reset_gpio, "eth-phy-reset"))
106			return 0;
107	
108		/* RESET_PU */
109		gpio_direction_output(phy_reset_gpio, 0);
110		mdelay(20);
111	
112		gpio_direction_output(phy_reset_gpio, 1);
113		/* RC charging time */
114		mdelay(60);
115	
116		return 0;
117	}
118	
119	void bm_dwmac_exit(struct platform_device *pdev, void *priv)
120	{
121		struct cvitek_mac *bsp_priv = priv;
122	
123		clk_disable_unprepare(bsp_priv->gate_clk_500m);
124		clk_disable_unprepare(bsp_priv->gate_clk_axi4);
125	}
126	
127	static int bm_dwmac_probe(struct platform_device *pdev)
128	{
129		struct plat_stmmacenet_data *plat_dat;
130		struct stmmac_resources stmmac_res;
131		struct cvitek_mac *bsp_priv = NULL;
132		int ret;
133	
134		pdev->dev.dma_mask = &bm_dma_mask;
135		pdev->dev.coherent_dma_mask = bm_dma_mask;
136	
137		bm_eth_reset_phy(pdev);
138	
139		ret = stmmac_get_platform_resources(pdev, &stmmac_res);
140		if (ret)
141			return ret;
142	
143		plat_dat = stmmac_probe_config_dt(pdev, &stmmac_res.mac);
144		if (IS_ERR(plat_dat))
145			return PTR_ERR(plat_dat);
146	
147		ret = stmmac_dvr_probe(&pdev->dev, plat_dat, &stmmac_res);
148		if (ret)
149			goto err_remove_config_dt;
150	
151		bsp_priv = devm_kzalloc(&pdev->dev, sizeof(*bsp_priv), GFP_KERNEL);
152		if (!bsp_priv)
153			return PTR_ERR(bsp_priv);
154	
155		bsp_priv->dev = &pdev->dev;
156	
157		/* clock setup */
158		bsp_priv->gate_clk_500m = devm_clk_get(&pdev->dev, "clk_500m_eth");
159	
160		if (IS_ERR(bsp_priv->gate_clk_500m))
161			dev_warn(&pdev->dev, "Cannot get clk_500m_eth!\n");
162		else
163			clk_prepare_enable(bsp_priv->gate_clk_500m);
164	
165		bsp_priv->gate_clk_axi4 = devm_clk_get(&pdev->dev, "clk_axi4_eth");
166	
167		if (IS_ERR(bsp_priv->gate_clk_axi4))
168			dev_warn(&pdev->dev, "Cannot get gate_clk_axi4!\n");
169		else
170			clk_prepare_enable(bsp_priv->gate_clk_axi4);
171	
172		plat_dat->bsp_priv = bsp_priv;
173		plat_dat->exit = bm_dwmac_exit;
174	
175		return 0;
176	
177	err_remove_config_dt:
178		stmmac_remove_config_dt(pdev, plat_dat);
179	
180		return ret;
181	}
