2359	 */
2360	static void stmmac_tx_timer(struct timer_list *t)
2361	{
2362		struct stmmac_tx_queue *tx_q = from_timer(tx_q, t, txtimer);
2363		struct stmmac_priv *priv = tx_q->priv_data;
2364		struct stmmac_channel *ch;
