2369			unsigned long flags;
2370	
2371			spin_lock_irqsave(&ch->lock, flags);
2372			stmmac_disable_dma_irq(priv, priv->ioaddr, ch->index, 0, 1);
2373			spin_unlock_irqrestore(&ch->lock, flags);
2374			__napi_schedule(&ch->tx_napi);
2375		}
2376	}
