3475	
3476		skb_tx_timestamp(skb);
3477	
3478		/* Ready to fill the first descriptor and set the OWN bit w/o any
3479		 * problems because all the descriptors are actually ready to be
3480		 * passed to the DMA engine.
3481		 */
3482		if (likely(!is_jumbo)) {
3483			bool last_segment = (nfrags == 0);
3484	
3485			des = dma_map_single(priv->device, skb->data,
3486					     nopaged_len, DMA_TO_DEVICE);
3487			if (dma_mapping_error(priv->device, des))
3488				goto dma_map_err;
3489	
3490			tx_q->tx_skbuff_dma[first_entry].buf = des;
3491	
3492			stmmac_set_desc_addr(priv, first, des);
3493	
3494			tx_q->tx_skbuff_dma[first_entry].len = nopaged_len;
3495			tx_q->tx_skbuff_dma[first_entry].last_segment = last_segment;
3496	
3497			if (unlikely((skb_shinfo(skb)->tx_flags & SKBTX_HW_TSTAMP) &&
