3571	 * stmmac_rx_refill - refill used skb preallocated buffers
3572	 * @priv: driver private structure
3573	 * @queue: RX queue index
3574	 * Description : this is to reallocate the skb for the reception process
3575	 * that is based on zero-copy.
3576	 */
3577	static inline void stmmac_rx_refill(struct stmmac_priv *priv, u32 queue)
3578	{
3579		struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
3580		int len, dirty = stmmac_rx_dirty(priv, queue);
3581		unsigned int entry = rx_q->dirty_rx;
3582	
3583		len = DIV_ROUND_UP(priv->dma_buf_sz, PAGE_SIZE) * PAGE_SIZE;
3584	
3585		while (dirty-- > 0) {
3586			struct stmmac_rx_buffer *buf = &rx_q->buf_pool[entry];
3587			struct dma_desc *p;
3588			bool use_rx_wd;
3589	
3590			if (priv->extend_desc)
3591				p = (struct dma_desc *)(rx_q->dma_erx + entry);
3592			else
3593				p = rx_q->dma_rx + entry;
3594	
3595			if (!buf->page) {
3596				buf->page = page_pool_dev_alloc_pages(rx_q->page_pool);
3597				if (!buf->page)
3598					break;
3599			}
3600	
3601			if (priv->sph && !buf->sec_page) {
3602				buf->sec_page = page_pool_dev_alloc_pages(rx_q->page_pool);
3603				if (!buf->sec_page)
3604					break;
3605	
3606				buf->sec_addr = page_pool_get_dma_addr(buf->sec_page);
3607	
3608				dma_sync_single_for_device(priv->device, buf->sec_addr,
3609							   len, DMA_FROM_DEVICE);
3610			}
3611	
3612			buf->addr = page_pool_get_dma_addr(buf->page);
3613	
3614			/* Sync whole allocation to device. This will invalidate old
3615			 * data.
3616			 */

4080	 *  @dev_id: to pass the net device pointer (must be valid).
4081	 *  Description: this is the main driver interrupt service routine.
4082	 *  It can call:
4083	 *  o DMA service routine (to manage incoming frame reception and transmission
4084	 *    status)
4085	 *  o Core interrupts to manage: remote wake-up, management counter, LPI
4086	 *    interrupts.
4087	 */
4088	static irqreturn_t stmmac_interrupt(int irq, void *dev_id)
4089	{
4090		struct net_device *dev = (struct net_device *)dev_id;
4091		struct stmmac_priv *priv = netdev_priv(dev);
4092		u32 rx_cnt = priv->plat->rx_queues_to_use;
4093		u32 tx_cnt = priv->plat->tx_queues_to_use;
4094		u32 queues_count;
4095		u32 queue;
4096		bool xmac;
4097	
4098		xmac = priv->plat->has_gmac4 || priv->plat->has_xgmac;
4099		queues_count = (rx_cnt > tx_cnt) ? rx_cnt : tx_cnt;
4100	
4101		if (priv->irq_wake)
4102			pm_wakeup_event(priv->device, 0);
4103	
4104		/* Check if adapter is up */
4105		if (test_bit(STMMAC_DOWN, &priv->state))
4106			return IRQ_HANDLED;
4107		/* Check if a fatal error happened */
4108		if (stmmac_safety_feat_interrupt(priv))
4109			return IRQ_HANDLED;
4110	
4111		/* To handle GMAC own interrupts */
4112		if ((priv->plat->has_gmac) || xmac) {
4113			int status = stmmac_host_irq_status(priv, priv->hw, &priv->xstats);
4114			int mtl_status;
4115	
4116			if (unlikely(status)) {
4117				/* For LPI we need to save the tx status */
4118				if (status & CORE_IRQ_TX_PATH_IN_LPI_MODE)
4119					priv->tx_path_in_lpi_mode = true;
4120				if (status & CORE_IRQ_TX_PATH_EXIT_LPI_MODE)
4121					priv->tx_path_in_lpi_mode = false;
4122			}
4123	
4124			for (queue = 0; queue < queues_count; queue++) {
4125				struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
4126	
4127				mtl_status = stmmac_host_mtl_irq_status(priv, priv->hw,
4128									queue);
4129				if (mtl_status != -EINVAL)
4130					status |= mtl_status;
4131	
4132				if (status & CORE_IRQ_MTL_RX_OVERFLOW)
4133					stmmac_set_rx_tail_ptr(priv, priv->ioaddr,
4134							       rx_q->rx_tail_addr,
4135							       queue);
4136			}
4137	
4138			/* PCS link status */
4139			if (priv->hw->pcs) {
4140				if (priv->xstats.pcs_link)
4141					netif_carrier_on(dev);
4142				else
4143					netif_carrier_off(dev);
4144			}
4145		}
4146	
4147		/* To handle DMA interrupts */
4148		stmmac_dma_interrupt(priv);
4149	
4150		return IRQ_HANDLED;
4151	}
