3700	 * It gets all the frames inside the ring.
3701	 */
3702	static int stmmac_rx(struct stmmac_priv *priv, int limit, u32 queue)
3703	{
3704		struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
3705		struct stmmac_channel *ch = &priv->channel[queue];
3706		unsigned int count = 0, error = 0, len = 0;
3707		int status = 0, coe = priv->hw->rx_csum;
3708		unsigned int next_entry = rx_q->cur_rx;
3709		struct sk_buff *skb = NULL;
3710	
3711		if (netif_msg_rx_status(priv)) {
3712			void *rx_head;
3713	
3714			netdev_dbg(priv->dev, "%s: descriptor ring:\n", __func__);
3715			if (priv->extend_desc)
3716				rx_head = (void *)rx_q->dma_erx;
3717			else
3718				rx_head = (void *)rx_q->dma_rx;
3719	
3720			stmmac_display_ring(priv, rx_head, priv->dma_rx_size, true);
3721		}
3722		while (count < limit) {
3723			unsigned int buf1_len = 0, buf2_len = 0;
3724			enum pkt_hash_types hash_type;
3725			struct stmmac_rx_buffer *buf;
3726			struct dma_desc *np, *p;
3727			int entry;
3728			u32 hash;
3729	
3730			if (!count && rx_q->state_saved) {
3731				skb = rx_q->state.skb;
3732				error = rx_q->state.error;
3733				len = rx_q->state.len;
3734			} else {
3735				rx_q->state_saved = false;
3736				skb = NULL;
3737				error = 0;
3738				len = 0;
3739			}
3740	
3741			if (count >= limit)
3742				break;
3743	
3744	read_again:
3745			buf1_len = 0;
3746			buf2_len = 0;
3747			entry = next_entry;
3748			buf = &rx_q->buf_pool[entry];
3749	
3750			if (priv->extend_desc)
3751				p = (struct dma_desc *)(rx_q->dma_erx + entry);
3752			else
3753				p = rx_q->dma_rx + entry;
3754	
3755			/* read the status of the incoming frame */
3756			status = stmmac_rx_status(priv, &priv->dev->stats,
3757					&priv->xstats, p);
3758			/* check if managed by the DMA otherwise go ahead */
3759			if (unlikely(status & dma_own))
3760				break;
3761	
3762			rx_q->cur_rx = STMMAC_GET_ENTRY(rx_q->cur_rx,
3763							priv->dma_rx_size);
3764			next_entry = rx_q->cur_rx;
3765	
3766			if (priv->extend_desc)
3767				np = (struct dma_desc *)(rx_q->dma_erx + next_entry);
3768			else
3769				np = rx_q->dma_rx + next_entry;
3770	
3771			prefetch(np);
3772	
3773			if (priv->extend_desc)
3774				stmmac_rx_extended_status(priv, &priv->dev->stats,
3775						&priv->xstats, rx_q->dma_erx + entry);
3776			if (unlikely(status == discard_frame)) {
3777				page_pool_recycle_direct(rx_q->page_pool, buf->page);
3778				buf->page = NULL;
3779				error = 1;
3780				if (!priv->hwts_rx_en)
3781					priv->dev->stats.rx_errors++;
3782			}
3783	
3784			if (unlikely(error && (status & rx_not_ls)))
3785				goto read_again;
3786			if (unlikely(error)) {
3787				dev_kfree_skb(skb);
3788				skb = NULL;
3789				count++;
3790				continue;
3791			}
3792	
3793			/* Buffer is good. Go on. */
3794	
3795			prefetch(page_address(buf->page));
3796			if (buf->sec_page)
3797				prefetch(page_address(buf->sec_page));
3798	
3799			buf1_len = stmmac_rx_buf1_len(priv, p, status, len);
3800			len += buf1_len;
3801			buf2_len = stmmac_rx_buf2_len(priv, p, status, len);
3802			len += buf2_len;
3803	
3804			/* ACS is set; GMAC core strips PAD/FCS for IEEE 802.3
3805			 * Type frames (LLC/LLC-SNAP)
3806			 *
3807			 * llc_snap is never checked in GMAC >= 4, so this ACS
3808			 * feature is always disabled and packets need to be
3809			 * stripped manually.
3810			 */
3811			if (likely(!(status & rx_not_ls)) &&
3812			    (likely(priv->synopsys_id >= DWMAC_CORE_4_00) ||
3813			     unlikely(status != llc_snap))) {
3814				if (buf2_len)
3815					buf2_len -= ETH_FCS_LEN;
3816				else
3817					buf1_len -= ETH_FCS_LEN;
3818	
3819				len -= ETH_FCS_LEN;
3820			}
3821	
3822			if (!skb) {
3823				skb = napi_alloc_skb(&ch->rx_napi, buf1_len);
3824				if (!skb) {
3825					priv->dev->stats.rx_dropped++;
3826					count++;
3827					goto drain_data;
3828				}
3829	
3830				dma_sync_single_for_cpu(priv->device, buf->addr,
3831							buf1_len, DMA_FROM_DEVICE);
3832				skb_copy_to_linear_data(skb, page_address(buf->page),
3833							buf1_len);
3834				skb_put(skb, buf1_len);
3835	
3836				/* Data payload copied into SKB, page ready for recycle */
3837				page_pool_recycle_direct(rx_q->page_pool, buf->page);
3838				buf->page = NULL;
3839			} else if (buf1_len) {
3840				dma_sync_single_for_cpu(priv->device, buf->addr,
3841							buf1_len, DMA_FROM_DEVICE);
3842				skb_add_rx_frag(skb, skb_shinfo(skb)->nr_frags,
3843						buf->page, 0, buf1_len,
3844						priv->dma_buf_sz);
3845	
3846				/* Data payload appended into SKB */
3847				page_pool_release_page(rx_q->page_pool, buf->page);
3848				buf->page = NULL;
3849			}
3850	
3851			if (buf2_len) {
3852				dma_sync_single_for_cpu(priv->device, buf->sec_addr,
3853							buf2_len, DMA_FROM_DEVICE);
3854				skb_add_rx_frag(skb, skb_shinfo(skb)->nr_frags,
3855						buf->sec_page, 0, buf2_len,
3856						priv->dma_buf_sz);
3857	
3858				/* Data payload appended into SKB */
3859				page_pool_release_page(rx_q->page_pool, buf->sec_page);
3860				buf->sec_page = NULL;
3861			}
3862	
3863	drain_data:
3864			if (likely(status & rx_not_ls))
3865				goto read_again;
3866			if (!skb)
3867				continue;
3868	
3869			/* Got entire packet into SKB. Finish it. */
3870	
3871			stmmac_get_rx_hwtstamp(priv, p, np, skb);
3872			stmmac_rx_vlan(priv->dev, skb);
3873			skb->protocol = eth_type_trans(skb, priv->dev);
3874	
3875			if (unlikely(!coe))
3876				skb_checksum_none_assert(skb);
3877			else
3878				skb->ip_summed = CHECKSUM_UNNECESSARY;
3879	
3880			if (!stmmac_get_rx_hash(priv, p, &hash, &hash_type))
3881				skb_set_hash(skb, hash, hash_type);
3882	
3883			skb_record_rx_queue(skb, queue);
3884			napi_gro_receive(&ch->rx_napi, skb);
3885			skb = NULL;
3886	
3887			priv->dev->stats.rx_packets++;
3888			priv->dev->stats.rx_bytes += len;
3889			count++;
3890		}
3891	
3892		if (status & rx_not_ls || skb) {
3893			rx_q->state_saved = true;
3894			rx_q->state.skb = skb;
3895			rx_q->state.error = error;
3896			rx_q->state.len = len;
3897		}
3898	
3899		stmmac_rx_refill(priv, queue);
3900	
3901		priv->xstats.rx_pkt_n += count;
3902	
3903		return count;
3904	}
