3906	static int stmmac_napi_poll_rx(struct napi_struct *napi, int budget)
3907	{
3908		struct stmmac_channel *ch =
3909			container_of(napi, struct stmmac_channel, rx_napi);
3910		struct stmmac_priv *priv = ch->priv_data;
3911		u32 chan = ch->index;
3912		int work_done;
3913	
3914		priv->xstats.napi_poll++;
3915	
3916		work_done = stmmac_rx(priv, budget, chan);
3917		if (work_done < budget && napi_complete_done(napi, work_done)) {
3918			unsigned long flags;
3919	
3920			spin_lock_irqsave(&ch->lock, flags);
3921			stmmac_enable_dma_irq(priv, priv->ioaddr, chan, 1, 0);
3922			spin_unlock_irqrestore(&ch->lock, flags);
3923		}
3924	
3925		return work_done;
3926	}
3927	
3928	static int stmmac_napi_poll_tx(struct napi_struct *napi, int budget)
3929	{
3930		struct stmmac_channel *ch =
3931			container_of(napi, struct stmmac_channel, tx_napi);
3932		struct stmmac_priv *priv = ch->priv_data;
3933		u32 chan = ch->index;
3934		int work_done;
3935	
3936		priv->xstats.napi_poll++;
3937	
3938		work_done = stmmac_tx_clean(priv, priv->dma_tx_size, chan);
3939		work_done = min(work_done, budget);
3940	
3941		if (work_done < budget && napi_complete_done(napi, work_done)) {
3942			unsigned long flags;
3943	
3944			spin_lock_irqsave(&ch->lock, flags);
3945			stmmac_enable_dma_irq(priv, priv->ioaddr, chan, 0, 1);
3946			spin_unlock_irqrestore(&ch->lock, flags);
3947		}
3948	
3949		return work_done;
3950	}
